// Extraer mensaje y remitente según el proveedor (Evolution API o WhatsApp Cloud API)
const body = $input.item.json.body || $input.item.json;
let fromNumber = '';
let messageText = '';

if (body.data && body.data.key) {
  // Formato Evolution API
  fromNumber = body.data.key.remoteJid;
  messageText = body.data.message?.conversation || body.data.message?.extendedTextMessage?.text || '';
} else if (body.entry && body.entry[0]?.changes[0]?.value?.messages) {
  // Formato Meta Cloud API
  const msg = body.entry[0].changes[0].value.messages[0];
  fromNumber = msg.from;
  messageText = msg.text?.body || '';
} else {
  fromNumber = body.from || 'test_user';
  messageText = body.message || body.text || '';
}

return {
  json: {
    sessionId: fromNumber,
    fromNumber,
    messageText,
    timestamp: new Date().toISOString()
  }
};
